function loadHtml2CanvasLib(callback) {

  if (_html2canvasReady || window.html2canvas) {

    _html2canvasReady = true;

    callback(true);

    return;

  }

  const cdns = [

    "https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js",

    "https://unpkg.com/html2canvas@1.4.1/dist/html2canvas.min.js",

  ];

  function tryLoad(idx) {

    if (idx >= cdns.length) {

      callback(false);

      return;

    }

    const s = document.createElement("script");

    s.src = cdns[idx];

    const t = setTimeout(function () {

      s.onload = s.onerror = null;

      tryLoad(idx + 1);

    }, 8000);

    s.onload = function () {

      clearTimeout(t);

      if (window.html2canvas) {

        _html2canvasReady = true;

        callback(true);

      } else tryLoad(idx + 1);

    };

    s.onerror = function () {

      clearTimeout(t);

      tryLoad(idx + 1);

    };

    const hostDocument = document.defaultView && document.defaultView.document
      ? document.defaultView.document
      : document;
    hostDocument.head.appendChild(s);

  }

  tryLoad(0);

}



