    function buildTipUpdateFingerprint(context, rules) {
      var metrics = ['detailOriginalTips', 'detailPoolAmount'].map(function(id) { return ((document.getElementById(id) || {}).textContent || '').trim(); });
      var payload = { store: context.store, dateKey: context.dateKey, rules: rules || [], originalTipMetrics: metrics };
      return TipOutDateState.canonical ? TipOutDateState.canonical(payload) : JSON.stringify(payload);
    }
