        TipOutDateState.assertDateWritable(context.store, context.dateKey);
        var rules = ruleData.getRulesForStore(context.store);
        var fingerprint = buildTipUpdateFingerprint(context, rules);
        if (!rules.length) throw new Error('当前门店没有可用的小费分配规则');
        var currentScope = getDetailPayoutScope();
        if (context.intentVersion !== tipDataUpdateIntentVersion || currentScope.store !== context.store || currentScope.dateKey !== context.dateKey) throw new Error('门店或日期已变化，请重新更新小费数据');
        TipOutDateState.assertDateWritable(context.store, context.dateKey);
