    var WEEKDAY_COND_OPTIONS = [
      { v: '1', l: '星期一' }, { v: '2', l: '星期二' }, { v: '3', l: '星期三' }, { v: '4', l: '星期四' },
      { v: '5', l: '星期五' }, { v: '6', l: '星期六' }, { v: '7', l: '星期日' }
    ];
