    function saveManualCondition() {
      if (currentEditingRuleId) {
        var mc = collectManualConditions();
        normalizeConditionsRoleEmployeeExclusive(mc);
        poolRuleConditions[currentEditingRuleId] = mc;
        updatePoolRuleConditionDisplay(currentEditingRuleId);
      }
      closeDrawer('manualDrawer');
      showNotification(tipTerm('手动上报小费取值条件保存成功'));
    }

    function collectManualConditions() {
      var cond = {};
      var container = document.getElementById('manualConditionsContainer');
      if (!container) return cond;
      container.querySelectorAll('.condition-card').forEach(function(card) {
        var id = card.id || '';
        var type = id.replace('manual-cond-', '');
        if (!type) return;
        if (type === 'role') {
          var roleMs = card.querySelector('.role-role-select');
          if (roleMs) {
            var checked = roleMs.querySelectorAll('input[type="checkbox"]:checked');
            cond.role = Array.from(checked).map(function(c) { return c.value; });
          }
        } else if (type === 'employee') {
          var manualEcRoleMs = card.querySelector('.employee-condition-role-select');
          var manualEcStaffMs = card.querySelector('.employee-condition-staff-select');
          if (manualEcRoleMs) {
            cond.employeeRoles = Array.from(manualEcRoleMs.querySelectorAll('input[type="checkbox"]:checked')).map(function(c) { return c.value; });
          }
          if (manualEcStaffMs) {
            cond.employee = Array.from(manualEcStaffMs.querySelectorAll('input[type="checkbox"]:not(.role-employee-select-all-cb):checked')).map(function(c) { return c.value; });
          }
        } else if (type === 'hours') {
          var inputs = card.querySelectorAll('input[type="time"]');
          cond.hours = { start: inputs[0] ? inputs[0].value : '', end: inputs[1] ? inputs[1].value : '' };
        } else if (type === 'shift') {
          var shiftMs = card.querySelector('.shift-condition-select');
          if (shiftMs) {
            var shiftChecked = shiftMs.querySelectorAll('input[type="checkbox"]:checked');
            cond.shift = Array.from(shiftChecked).map(function(c) { return c.value; });
          }
        } else if (type === 'weekday') {
          var wMs = card.querySelector('.weekday-condition-select');
          if (wMs) {
            var wChecked = wMs.querySelectorAll('input[type="checkbox"]:checked');
            cond.weekdays = Array.from(wChecked).map(function(c) { return c.value; });
          }
        }
      });
      return cond;
    }

